path = ROOT / "etl4/database/_schema_docs.py"
source = (HERE / "before/etl4/database/_schema_docs.py").read_text(encoding="utf-8-sig")
tree = ast.parse(source)
lines = source.splitlines(keepends=True)
for node in reversed(tree.body):
    if isinstance(node, ast.Assign) and isinstance(node.targets[0], ast.Name) and node.targets[0].id in ("SOURCES", "SPECIAL"):
        name = node.targets[0].id
        new = globals()[name]
        assert list(ast.literal_eval(node.value)) == list(new), name
        lines[node.lineno - 1:node.end_lineno] = [name + " = " + pformat(new, sort_dicts=False, width=110) + "\n"]
source = "".join(lines).replace('"""\u6839\u636e\u6570\u636e\u5e93\u5b9e\u9645\u7ed3\u6784\u751f\u6210\u5b57\u6bb5\u4e0e\u6765\u6e90\u8bf4\u660e\u3002"""', '"""Generate field and source descriptions from the database schema.\n\n\u6839\u636e\u6570\u636e\u5e93\u5b9e\u9645\u7ed3\u6784\u751f\u6210\u5b57\u6bb5\u4e0e\u6765\u6e90\u8bf4\u660e\u3002\n"""')
for chinese, english in TEXT.items():
    assert chinese in source, chinese
    source = source.replace(chinese, english)
ast.parse(source)
path.write_text(source, encoding="utf-8", newline="\n")
(ROOT / 'github-upload/etl4/database/_schema_docs.py').write_bytes(path.read_bytes())
print("Translated schema descriptions and synchronized the upload copy")
